select*from user;
select*from artist;
select*from genre;
select*from song;
select*from streaming;
select*from likes;

-- 테이블 데이터 삭제
SET FOREIGN_KEY_CHECKS = 0;
TRUNCATE TABLE likes;
SET FOREIGN_KEY_CHECKS = 1;

-- 스트리밍 수 확인
SELECT
    s.song_id,
    s.song_name '노래 제목',
    a.artist_name '아티스트',
    COUNT(st.streaming_id) AS '스트리밍 수'
FROM song s
JOIN artist a
    ON s.artist_artist_id = a.artist_id
LEFT JOIN streaming st
    ON s.song_id = st.song_song_id
GROUP BY
    s.song_id,
    s.song_name,
    a.artist_name
ORDER BY
    '스트리밍 수' DESC;

-- 좋아요 수 확인
SELECT
    s.song_id,
    s.song_name '노래 제목',
    a.artist_name '아티스트',
    COUNT(l.likes_id) AS '좋아요 수'
FROM song s
JOIN artist a
    ON s.artist_artist_id = a.artist_id
LEFT JOIN likes l
    ON s.song_id = l.song_song_id
GROUP BY
    s.song_id,
    s.song_name,
    a.artist_name
ORDER BY
    '좋아요 수' DESC;
 
-- 아티스트별 전체 스트리밍 수
SELECT a.artist_name '아티스트', COUNT(*) AS '총 스트리밍 수'
FROM streaming s
JOIN song so ON s.song_song_id = so.song_id
JOIN artist a ON so.artist_artist_id = a.artist_id
GROUP BY a.artist_id
ORDER BY '총 스트리밍 수' DESC;

-- 장르별 좋아요 수 합계
SELECT g.genre_name '장르', COUNT(*) AS '좋아요 수'
FROM likes l
JOIN song s ON l.song_song_id = s.song_id
JOIN genre g ON s.genre_genre_id = g.genre_id
GROUP BY g.genre_id
ORDER BY '좋아요 수' DESC;

-- 특정 장르에서 가장 인기 많은 곡
SELECT s.song_name '노래 제목', a.artist_name '아티스트', COUNT(l.likes_id) AS '좋아요'
FROM song s
JOIN likes l ON s.song_id = l.song_song_id
JOIN artist a ON s.artist_artist_id = a.artist_id
WHERE s.genre_genre_id = 'G07' -- 장르: 포크/블루스
GROUP BY s.song_id
ORDER BY '좋아요' DESC;

-- 1. 아티스트별 전체 스트리밍 수를 조회하시오.
SELECT a.artist_name '아티스트',
       COUNT(st.streaming_id) AS '총 스트리밍 수'
FROM artist a
JOIN song s ON a.artist_id = s.artist_artist_id
LEFT JOIN streaming st ON s.song_id = st.song_song_id
GROUP BY a.artist_name
ORDER BY COUNT(st.streaming_id) DESC;

-- 2. 장르별 좋아요 수 합계를 조회하시오.
SELECT g.genre_name '장르',
       COUNT(l.likes_id) AS '총 좋아요 수'
FROM genre g
JOIN song s ON g.genre_id = s.genre_genre_id
LEFT JOIN likes l ON s.song_id = l.song_song_id
GROUP BY g.genre_name
ORDER BY COUNT(l.likes_id) DESC;

-- 3. 좋아요를 가장 많이 받은 노래 TOP 20을 조회하시오.
SELECT 
    s.song_name AS '노래 제목',
    a.artist_name AS '아티스트',
    COUNT(l.likes_id) AS '총 좋아요 수'
FROM song s
JOIN artist a ON s.artist_artist_id = a.artist_id
LEFT JOIN likes l ON s.song_id = l.song_song_id
GROUP BY s.song_id, s.song_name, a.artist_name
ORDER BY COUNT(l.likes_id) DESC
LIMIT 20;


-- 4. 스트리밍 횟수가 가장 많은 노래 TOP 20을 조회하시오.
SELECT s.song_name '노래 제목',
       a.artist_name '아티스트',
       COUNT(st.streaming_id) AS '총 스트리밍 수'
FROM song s
JOIN artist a ON s.artist_artist_id = a.artist_id
LEFT JOIN streaming st ON s.song_id = st.song_song_id
GROUP BY s.song_id, s.song_name, a.artist_name
ORDER BY COUNT(st.streaming_id) DESC
LIMIT 20;


-- 5. 특정 유저(U001)가 재생한 노래 목록을 조회하시오.
SELECT u.user_name '유저',
       s.song_name '노래 제목',
       a.artist_name '아티스트',
       st.streaming_date '스트리밍 날짜'
FROM streaming st
JOIN user u ON st.user_user_id = u.user_id
JOIN song s ON st.song_song_id = s.song_id
JOIN artist a ON s.artist_artist_id = a.artist_id
WHERE st.user_user_id = 'U491'
ORDER BY st.streaming_date DESC;

-- 6. 특정 아티스트(A124)의 노래 중 좋아요 순위를 조회하시오.
SELECT a.artist_name '아티스트',
       s.song_name '노래 제목',
       COUNT(l.likes_id) AS '총 좋아요 수'
FROM song s
JOIN artist a ON s.artist_artist_id = a.artist_id
LEFT JOIN likes l ON s.song_id = l.song_song_id
WHERE s.artist_artist_id = 'A124' -- > 아이유
GROUP BY a.artist_name, s.song_id, s.song_name
ORDER BY COUNT(l.likes_id) DESC;

-- 7. 특정 장르(힙합)의 노래별 스트리밍 수를 조회하시오.
SELECT g.genre_name '장르',
       s.song_name '노래 제목',
       a.artist_name '아티스트',
       COUNT(st.streaming_id) AS '총 스트리밍 수'
FROM song s
JOIN genre g ON s.genre_genre_id = g.genre_id
JOIN artist a ON s.artist_artist_id = a.artist_id
LEFT JOIN streaming st ON s.song_id = st.song_song_id
WHERE g.genre_name = '힙합'
GROUP BY g.genre_name, s.song_id, s.song_name, a.artist_name
ORDER BY COUNT(st.streaming_id) DESC;

-- 8. 최근 1년 동안 스트리밍된 곡 목록을 조회하시오.
SELECT 
    s.song_name AS '노래 제목',
    a.artist_name AS '아티스트',
    st.streaming_date AS '스트리밍 날짜'
FROM streaming st
JOIN song s ON st.song_song_id = s.song_id
JOIN artist a ON s.artist_artist_id = a.artist_id
WHERE st.streaming_date >= DATE_SUB(CURDATE(), INTERVAL 1 YEAR)
ORDER BY st.streaming_date DESC;

-- 9. 가장 오래 꾸준히 스트리밍된 노래 TOP 20을 조회하시오.
SELECT 
    so.song_name AS '노래 제목',
    a.artist_name AS '아티스트',
    MIN(st.streaming_date) AS '첫 스트리밍 날짜',
    MAX(st.streaming_date) AS '마지막 스트리밍 날짜',
    DATEDIFF(MAX(st.streaming_date), MIN(st.streaming_date)) AS '스트리밍 지속 일수'
FROM song so
JOIN artist a ON so.artist_artist_id = a.artist_id
JOIN streaming st ON so.song_id = st.song_song_id
GROUP BY so.song_id, so.song_name, a.artist_name
ORDER BY DATEDIFF(MAX(st.streaming_date), MIN(st.streaming_date)) DESC
LIMIT 20;


-- 10. 장르별 스트리밍 수 TOP 순위를 조회하시오.
SELECT
    g.genre_name AS '장르',
    COUNT(st.streaming_id) AS '총 스트리밍 수'
FROM genre g
JOIN song s ON g.genre_id = s.genre_genre_id
LEFT JOIN streaming st ON s.song_id = st.song_song_id
GROUP BY g.genre_name
ORDER BY COUNT(st.streaming_id) DESC;




